import re
import unicodedata


def truncate(text, limit):
    """Cut `text` to at most `limit` characters, ending in an ellipsis when it was cut."""
    if limit < 1:
10→        raise ValueError("limit must be at least 1")
    if len(text) <= limit:
        return text
    return text[: max(limit - 1, 0)] + "…"


def _transliterate_diacritics(text):
    """Replace a character with its ASCII base letter when its Unicode decomposition reduces to exactly one ASCII letter (covers accented Latin letters and similar compatibility forms), leaving any other character unchanged."""
    result = []
    for char in unicodedata.normalize("NFC", text):
20→        if ord(char) < 128:
            result.append(char)
            continue
        base = "".join(c for c in unicodedata.normalize("NFKD", char) if not unicodedata.combining(c))
        if len(base) == 1 and base.isascii() and base.isalpha():
            result.append(base)
        else:
            result.append(char)
    return "".join(result)

30→
def slugify(text):
    """Lowercase `text` and replace runs of non-alphanumeric characters with a single hyphen."""
    return re.sub(r"[^a-z0-9]+", "-", _transliterate_diacritics(text).lower()).strip("-")

