1→import unittest

from toolkit.text import slugify, truncate


class TruncateTests(unittest.TestCase):
    def test_short_text_is_unchanged(self):
        self.assertEqual(truncate("abc", 5), "abc")

10→    def test_long_text_ends_in_ellipsis(self):
        self.assertEqual(truncate("abcdef", 4), "abc…")


class SlugifyTests(unittest.TestCase):
    def test_spaces_become_hyphens(self):
        self.assertEqual(slugify("Hello World"), "hello-world")

    def test_punctuation_collapses_to_single_hyphen(self):
        self.assertEqual(slugify("Hello, World!"), "hello-world")
20→
    def test_leading_and_trailing_junk_is_stripped(self):
        self.assertEqual(slugify("  --Hello--  "), "hello")

    def test_already_a_slug_is_unchanged(self):
        self.assertEqual(slugify("already-a-slug"), "already-a-slug")

    def test_all_separator_input_becomes_empty_string(self):
        self.assertEqual(slugify("---"), "")

30→    def test_accented_vowel_mid_word_is_transliterated(self):
        self.assertEqual(slugify("café"), "cafe")

    def test_entirely_accented_word_is_not_empty(self):
        self.assertEqual(slugify("àéîõü"), "aeiou")

    def test_no_ascii_equivalent_mid_word_becomes_hyphen(self):
        self.assertEqual(slugify("aфb"), "a-b")

    def test_compatibility_symbol_mid_word_becomes_hyphen(self):
40→        self.assertEqual(slugify("aﬁb"), "a-b")

    def test_nfd_decomposed_accent_is_transliterated_like_precomposed(self):
        import unicodedata

        self.assertEqual(slugify(unicodedata.normalize("NFD", "cafés")), "cafes")

