def slugify(text):
    """Lowercase `text` and replace runs of non-alphanumeric characters with a single hyphen."""
    return re.sub(r"[^a-z0-9]+", "-", _transliterate_diacritics(text).lower()).strip("-")


def is_palindrome(text):
    """Return True when `text` reads the same forwards and backwards, ignoring case and non-alphanumeric characters."""
    kept = "".join(c.lower() for c in unicodedata.normalize("NFC", text) if c.isalnum())
    return kept == kept[::-1]

